import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { ComparisonBars } from "@/components/analytics/charts";
import { StartWorkoutButton } from "@/components/diagnosis/start-workout-button";
import { startRecommendedPractice } from "@/app/practice/actions";
import { getCurrentUser } from "@/lib/auth/session";
import { compareDiagnosticSummaries, getDiagnosticResult } from "@/lib/diagnostic/service";
import { getGuestOwnerHash } from "@/lib/guest/identity";
import { getPreferences } from "@/lib/i18n/get-translations";
import { guestContinuationPath } from "@/lib/auth/redirect";

export default async function DiagnosticResultPage({ params }: { params: Promise<{ runId: string }> }) {
  const [{ runId }, user, guest] = await Promise.all([params, getCurrentUser(), getGuestOwnerHash()]);
  if (!user && !guest) redirect("/sign-in");
  const result = await getDiagnosticResult(runId, user ? { userId: user.id } : { guestOwnerHash: guest! });
  if (!result) notFound();
  const vi = (await getPreferences(user?.id)).interfaceLanguage === "vi";
  const section = (area: "LISTENING" | "READING") => { const rows = result.run.children.filter((row) => row.skillArea === area); const total = rows.reduce((n, row) => n + (row.scoreTotal ?? 0), 0); const correct = rows.reduce((n, row) => n + (row.scoreCorrect ?? 0), 0); return { total, correct, accuracy: total ? Math.round(correct / total * 100) : null }; };
  const listening = section("LISTENING"); const reading = section("READING");
  const summary = "summary" in result ? result.summary : null; const previous = "previous" in result ? result.previous : null;
  const comparison = summary && previous ? compareDiagnosticSummaries(summary, previous) : null;
  const deltaText = (value: number | null) => value === null ? (vi ? "Chưa đủ dữ liệu" : "Not enough data") : `${value > 0 ? "+" : ""}${value} ${vi ? "điểm %" : "percentage points"}`;
  return <main className="min-h-screen bg-slate-50 px-4 py-8 text-slate-900"><div className="mx-auto max-w-4xl">
    <p className="text-sm font-black uppercase tracking-wider text-teal-700">{vi ? "Đã hoàn thành đánh giá" : "Diagnostic complete"}</p>
    <h1 className="mt-2 text-3xl font-black sm:text-4xl">{result.run.purpose === "REASSESSMENT" ? (vi ? "Kết quả đánh giá lại" : "Reassessment result") : (vi ? "Hồ sơ TOEIC ban đầu" : "Initial TOEIC profile")}</h1>
    <p className="mt-3 text-slate-600">{vi ? "Độ chính xác thô tại một thời điểm; không phải điểm TOEIC quy đổi hay dự đoán." : "Raw checkpoint accuracy; not an official or predicted TOEIC score."}</p>
    <div className="mt-7 grid gap-4 sm:grid-cols-2">{[["Listening", listening], ["Reading", reading]].map(([name, data]) => { const item = data as typeof listening; return <article className="rounded-2xl border border-slate-200 bg-white p-6" key={String(name)}><h2 className="text-xl font-black">{String(name)}</h2><p className="mt-3 text-4xl font-black text-teal-700">{item.accuracy === null ? "—" : `${item.accuracy}%`}</p><p className="mt-2 text-slate-600">{item.correct}/{item.total} {vi ? "câu đúng" : "correct"}</p></article>; })}</div>
    <section className="mt-7 rounded-2xl border border-slate-200 bg-white p-6"><h2 className="text-xl font-black">Listening vs Reading</h2><div className="mt-5"><ComparisonBars items={[{ label: "Listening", accuracy: listening.accuracy, answered: listening.total }, { label: "Reading", accuracy: reading.accuracy, answered: reading.total }]} noData={vi ? "Chưa có dữ liệu" : "No data"}/></div></section>
    {comparison && summary && previous ? <section className="mt-7 rounded-2xl border border-teal-200 bg-white p-6" aria-labelledby="checkpoint-comparison"><p className="text-xs font-black uppercase tracking-wider text-teal-700">Premium</p><h2 className="mt-1 text-xl font-black" id="checkpoint-comparison">{vi ? "So với lần đánh giá trước" : "Compared with the previous assessment"}</h2><p className="mt-2 text-sm text-slate-600">{previous.completedAt.toLocaleDateString(vi ? "vi-VN" : "en-US")} → {summary.completedAt.toLocaleDateString(vi ? "vi-VN" : "en-US")}</p><div className="mt-5 grid gap-3 sm:grid-cols-3">{[[vi ? "Tổng thể" : "Overall", previous.overall, summary.overall, comparison.overallDelta], ["Listening", previous.listening, summary.listening, comparison.listeningDelta], ["Reading", previous.reading, summary.reading, comparison.readingDelta]].map(([label, before, after, delta]) => { const a = before as typeof summary.overall; const b = after as typeof summary.overall; return <article className="rounded-xl bg-slate-50 p-4" key={String(label)}><h3 className="font-black">{String(label)}</h3><p className="mt-2 text-lg font-bold">{a.accuracy}% → {b.accuracy}%</p><p className="text-sm text-slate-600">{b.correct}/{b.total} · {deltaText(delta as number | null)}</p></article>; })}</div><h3 className="mt-6 font-black">{vi ? "Theo Part" : "By Part"}</h3><div className="mt-3 grid gap-2 sm:grid-cols-2">{summary.parts.map((part) => { const old = previous.parts.find((item) => item.part === part.part)!; const delta = comparison.parts.find((item) => item.part === part.part)?.delta ?? null; return <div className="flex items-center justify-between gap-3 rounded-xl border border-slate-200 p-3" key={part.part}><strong>Part {part.part}</strong><span className="text-right text-sm">{old.accuracy}% → {part.accuracy}%<br/><span className="text-slate-500">{part.correct}/{part.total} · {deltaText(delta)}</span></span></div>; })}</div></section> : user && result.run.blueprintVersion === null ? <p className="mt-7 rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-900">{vi ? "Không thể so sánh trực tiếp với bài cũ vì cấu trúc bài chưa xác định phiên bản." : "This legacy assessment has an unknown blueprint and cannot be compared."}</p> : user ? <p className="mt-7 rounded-2xl border border-slate-200 bg-white p-5 text-sm text-slate-600">{vi ? "Hoàn thành thêm một bài đánh giá tương thích để bắt đầu so sánh." : "Complete another compatible assessment to begin comparing checkpoints."}</p> : null}
    {user ? <div className="mt-7 rounded-2xl bg-slate-900 p-6 text-white"><h2 className="text-xl font-black">{vi ? "Ưu tiên tiếp theo" : "Next priority"}</h2>{result.recommendation ? <form action={startRecommendedPractice} className="mt-4"><StartWorkoutButton idle={vi ? "Bắt đầu bài luyện đề xuất" : "Start recommended workout"} pending={vi ? "Đang tạo…" : "Building…"}/></form> : <Link className="mt-4 inline-flex rounded-xl bg-teal-400 px-5 py-3 font-bold text-slate-950" href="/practice">{vi ? "Chọn bài luyện" : "Choose practice"}</Link>}</div> : <section className="mt-7 rounded-2xl border border-teal-200 bg-teal-50 p-6"><h2 className="text-xl font-black">{vi ? "Lưu kết quả & tiếp tục miễn phí" : "Save your result & continue free"}</h2><p className="mt-2 text-slate-700">{vi ? "Tạo tài khoản để giữ hồ sơ Listening + Reading, nhận bài luyện đề xuất và theo dõi tiến bộ." : "Create an account to keep your Listening + Reading profile, receive recommended practice, and track progress."}</p><Link className="mt-4 inline-flex rounded-xl bg-teal-700 px-5 py-3 font-bold text-white" href={`/sign-up?from=guest-result&next=${encodeURIComponent(guestContinuationPath(runId))}`}>{vi ? "Lưu kết quả & tiếp tục miễn phí" : "Save result & continue free"}</Link><Link className="mt-4 ml-0 block font-bold text-teal-800 underline sm:ml-4 sm:inline" href={`/sign-in?next=${encodeURIComponent(guestContinuationPath(runId))}`}>{vi ? "Đã có tài khoản? Đăng nhập" : "Already have an account? Sign in"}</Link></section>}
  </div></main>;
}
